const generateSampleData = () => {
  if (!reportConfig.value)
    return []

  // Generar datos de ejemplo basados en los campos configurados
  const data = []
  const numRows = 150

  for (let i = 0; i < numRows; i++) {
    const row: any = {}

    reportConfig.value.selectedFields.forEach(field => {
      switch (field.type) {
        case 'varchar':
        case 'text':
          if (field.field === 'CUENTA')
          row[field.field] = `CUENTA-${1000 + i}`

          else if (field.field === 'USUARIO')
          row[field.field] = ['Juan Pérez', 'María García', 'Carlos López', 'Ana Martínez'][i % 4]

          else if (field.field === 'RFC')
          row[field.field] = `RFC${Math.random().toString(36).substring(2, 15).toUpperCase()}`

          else
          row[field.field] = `Texto ${i + 1}`

          break

        case 'double':
        case 'number':
        case 'integer':
          row[field.field] = Math.round(Math.random() * 10000 * 100) / 100
          break

        case 'date':
        case 'datetime': {
          const date = new Date()

          date.setDate(date.getDate() - Math.floor(Math.random() * 365))
          row[field.field] = date.toISOString().split('T')[0]
          break
        }

        case 'boolean':
          row[field.field] = Math.random() > 0.5
          break

        default:
          row[field.field] = `Valor ${i + 1}`
      }
    })

    data.push(row)
  }

  return data
}

const buildFiltersPayload = () => {
  const filters: any = {}

  console.log('Filtros aplicados:', appliedFilters.value)
  console.log('Mapa de filtros:', appliedFiltersMap)

  // Función recursiva para buscar filtros en grupos anidados
  const findFilterInConfig = (filters: any[], fieldName: string): any => {
    for (const filter of filters) {
      if (filter.type === 'filter' && filter.field === fieldName)
        return filter

      if (filter.type === 'group' && filter.children) {
        const found = findFilterInConfig(filter.children, fieldName)
        if (found)
          return found
      }
    }

    return null
  }

  // Agregar filtros aplicados
  appliedFilters.value.forEach(filter => {
    const fieldConfig = getFieldConfig(filter.field)
    if (fieldConfig) {
      // Convertir el valor según el tipo de campo
      let value = filter.value

      if (fieldConfig.type === 'date' || fieldConfig.type === 'datetime') {
        // Para fechas, asegurar formato correcto
        if (typeof value === 'string')
          value = new Date(value).toISOString().split('T')[0]
      }
      else if (fieldConfig.type === 'number' || fieldConfig.type === 'double' || fieldConfig.type === 'integer') {
        // Para números, convertir a número
        value = Number.parseFloat(value)
      }

      filters[filter.field] = value
    }
  })

  // Agregar búsqueda rápida si existe
  if (quickSearchQuery.value)
    filters._search = quickSearchQuery.value

  console.log('Payload de filtros construido:', filters)

  return filters
}

const buildSortingPayload = () => {
