// Calcular totales
const _calculateTotals = (field: any) => {
  if (!showTotals.value || !['number', 'double', 'integer', 'currency'].includes(field.type))
    return null

  const values = reportData.value.map(row => Number.parseFloat(row[field.field]) || 0)

  switch (field.aggregation) {
    case 'SUM':
      return values.reduce((a, b) => a + b, 0)
    case 'AVG':
      return values.length > 0 ? values.reduce((a, b) => a + b, 0) / values.length : 0
    case 'COUNT':
      return values.length
    case 'MIN':
      return Math.min(...values)
    case 'MAX':
      return Math.max(...values)
    default:
      return values.reduce((a, b) => a + b, 0)
  }
}

// Helpers
const _getFilterConfig = (fieldName: string) => {
  if (!reportConfig.value)
    return null

  // Buscar en los filtros configurados
  const findInFilters = (filters: any[]): any => {
    for (const filter of filters) {
      if (filter.type === 'filter' && filter.field === fieldName)
        return filter

      if (filter.type === 'group' && filter.children) {
        const found = findInFilters(filter.children)
        if (found)
          return found
      }
    }

    return null
  }

  return findInFilters(reportConfig.value.filters || [])
}

