                </VTab>
              </VTabs>
              <VBtnToggle
                v-model="density"
                mandatory
                density="compact"
              >
                <VBtn
                  value="comfortable"
                  icon
                  size="small"
                >
                  <VIcon
                    icon="tabler-line-height"
                    size="16"
                  />
                  <VTooltip activator="parent">
                    Cómodo
                  </VTooltip>
                </VBtn>
                <VBtn
                  value="default"
                  icon
                  size="small"
                >
                  <VIcon
                    icon="tabler-menu-2"
                    size="16"
                  />
                  <VTooltip activator="parent">
                    Normal
                  </VTooltip>
                </VBtn>
                <VBtn
                  value="compact"
                  icon
                  size="small"
                >
                  <VIcon
                    icon="tabler-list"
                    size="16"
                  />
                  <VTooltip activator="parent">
                    Compacto
                  </VTooltip>
                </VBtn>
              </VBtnToggle>
            </div>
          </VCol>
          <VCol cols="auto">
            <div class="d-flex align-center gap-2">
              <VBtn
                icon
                variant="text"
                color="primary"
                :aria-label="showFilterPanel ? 'Ocultar filtros' : 'Mostrar filtros'"
                @click="showFilterPanel = !showFilterPanel"
              >
                <VIcon icon="tabler-filter" />
                <VTooltip activator="parent">
                  {{ showFilterPanel ? 'Ocultar filtros' : 'Mostrar filtros' }}
                </VTooltip>
              </VBtn>
              <VTextField
                v-model="quickSearchQuery"
                placeholder="Buscar en todos los campos..."
                density="compact"
                variant="outlined"
                hide-details
                clearable
                class="quick-search"
                style="max-inline-size: 300px; min-inline-size: 300px;"
              >
                <template #prepend-inner>
                  <VIcon
                    icon="tabler-search"
                    size="18"
                  />
                </template>
              </VTextField>
              <VMenu :close-on-content-click="false">
                <template #activator="{ props }">
                  <VBtn
                    icon
                    variant="text"
                    v-bind="props"
                  >
                    <VIcon icon="tabler-columns" />
                    <VTooltip activator="parent">
                      Configurar columnas
                    </VTooltip>
                  </VBtn>
                </template>
                <VList
                  min-width="200"
                  class="pa-2"
                >
                  <VListItem
                    v-for="field in reportConfig?.selectedFields"
                    :key="field.field"
                    class="py-1 px-2"
                    style="min-block-size: 36px;"
                  >
                    <div
                      class="d-flex align-center gap-2"
                      style="inline-size: 100%;"
                    >
                      <VCheckbox
                        :model-value="visibleColumns.includes(field.field)"
                        hide-details
                        density="compact"
                        class="me-1"
                        style="margin-block-end: 0;"
                        @update:model-value="toggleColumnVisibility(field.field)"
                      />
                      <VListItemTitle
                        class="text-body-2"
                        style=" flex: 1;min-inline-size: 80px;"
                      >
                        {{ field.alias || field.field }}
                      </VListItemTitle>
                      <VBtn
                        icon
                        size="x-small"
                        variant="text"
                        @click.stop="freezeColumn(field.field)"
                      >
                        <VIcon
                          :icon="frozenColumns.includes(field.field) ? 'tabler-pin' : 'tabler-pin-filled'"
                          size="16"
                          :color="frozenColumns.includes(field.field) ? 'primary' : undefined"
                        />
                      </VBtn>
                    </div>
                  </VListItem>
                </VList>
              </VMenu>
            </div>
          </VCol>
        </VRow>
      </VCardText>
    </VCard>

    <!-- Contenido principal -->
    <div
      class="report-content"
      :class="{ 'with-filters': showFilterPanel }"
    >
      <!-- Panel de filtros -->
      <VNavigationDrawer
        v-model="showFilterPanel"
        :width="360"
        location="left"
        temporary
        class="filter-panel"
      >
        <VCard
          class="mb-0"
          variant="outlined"
        >
          <VCardText>
            <VRow>
              <VCol cols="12">
                <div class="d-flex align-center justify-space-between mb-2">
                  <h6 class="text-h6 font-weight-medium mb-0">
                    <VIcon
                      icon="tabler-filter"
                      start
                      class="me-1"
                    />
                    Filtros disponibles
                  </h6>
                  <VChip
                    v-if="appliedFilters.length"
                    size="small"
                    variant="tonal"
                    color="primary"
                  >
                    <VIcon
                      icon="tabler-check"
                      size="16"
                      start
                    />
                    {{ appliedFilters.length }} activos
                  </VChip>
                </div>
                <p class="text-body-2 text-medium-emphasis mb-4">
                  Refina los resultados del reporte usando los filtros configurados.
                </p>
              </VCol>
            </VRow>
            <!-- Chips de filtros activos -->
            <div
              v-if="appliedFilters.length > 0"
              class="mb-4"
            >
              <VChip
                v-for="filter in appliedFilters"
                :key="filter.field"
                closable
                size="small"
                class="ma-1"
                color="primary"
                variant="elevated"
                @click:close="removeFilter(filter.field)"
              >
                <VIcon
                  icon="tabler-filter"
                  start
                  size="16"
                />
                {{ getFieldConfig(filter.field)?.alias || filter.field }}: {{ filter.value }}
              </VChip>
            </div>
            <!-- Filtros disponibles usando el componente reutilizable -->
            <ReportFiltersPreview
              v-if="reportConfig?.filters"
              :filters="reportConfig.filters"
              :readonly="false"
              :loading="loading"
              @update:filters="handleFiltersUpdate"
              @apply-filters="applyAllFilters"
              @clear-filters="clearAllFilters"
            />
            <VAlert
              v-else
              type="info"
              variant="tonal"
              density="compact"
            >
              <template #prepend>
                <VIcon icon="tabler-info-circle" />
              </template>
              <div>
                <strong>Sin filtros configurados</strong>
                <p class="mb-0 mt-1">
                  Este reporte no tiene filtros configurados. Se mostrarán todos los datos disponibles.
                </p>
              </div>
            </VAlert>
          </VCardText>
        </VCard>
      </VNavigationDrawer>
      <!-- Tabla de datos -->
      <VCard class="flex-grow-1">
        <VCardText class="pa-0">
          <!-- Loading overlay -->
          <VOverlay
            v-model="loading"
            contained
            class="align-center justify-center"
          >
            <VProgressCircular
              indeterminate
              size="64"
            />
          </VOverlay>

          <!-- Loading overlay para datos -->
          <VOverlay
            v-model="store.reportLoading"
            contained
            class="align-center justify-center"
          >
            <VCard class="pa-4">
              <div class="d-flex align-center gap-3">
                <VProgressCircular
                  indeterminate
                  size="32"
                  color="primary"
                />
                <span class="text-body-1">Cargando datos del reporte...</span>
              </div>
            </VCard>
          </VOverlay>

          <!-- Error state -->
          <VAlert
            v-if="error || store.reportError"
            type="error"
            variant="tonal"
            class="ma-4"
          >
            {{ error || store.reportError }}
          </VAlert>

          <!-- Tabla -->
          <div
            v-if="!error && reportConfig"
            class="data-table-container"
          >
            <VTable
              :density="density"
              fixed-header
              :height="isFullscreen ? 'calc(100vh - 200px)' : '600'"
            >
              <thead>
                <tr>
                  <th
                    v-for="field in reportConfig.selectedFields.filter(f => visibleColumns.includes(f.field))"
                    :key="field.field"
                    :style="{
                      width: `${columnWidths[field.field]}px`,
                      textAlign: field.align || 'left',
                      position: frozenColumns.includes(field.field) ? 'sticky' : 'relative',
                      left: frozenColumns.includes(field.field) ? '0' : 'auto',
                      zIndex: frozenColumns.includes(field.field) ? 10 : 1,
                      backgroundColor: 'rgb(var(--v-theme-surface))',
                    }"
                    class="sortable-header"
                    @click="field.sortable !== false && toggleSort(field.field)"
                  >
                    <div
                      class="d-flex align-center"
                      :class="`justify-${field.align || 'start'}`"
                    >
                      <span class="font-weight-medium">{{ field.alias }}</span>
                      <div
                        v-if="field.sortable !== false"
                        class="ms-2 d-flex align-center"
                      >
                        <VIcon
                          :icon="getSortIcon(field.field)"
                          size="16"
                          :color="activeSorting.find(s => s.field === field.field) ? 'primary' : 'grey'"
                        />
                        <span
                          v-if="getSortIndex(field.field)"
                          class="text-caption ms-1"
                          style="color: rgb(var(--v-theme-primary));"
                        >
                          {{ getSortIndex(field.field) }}
                        </span>
                      </div>
                    </div>
                  </th>
                </tr>
              </thead>
              <tbody>
                <tr
                  v-for="(row, index) in paginatedData"
                  :key="index"
                >
                  <td
                    v-for="field in reportConfig.selectedFields.filter(f => visibleColumns.includes(f.field))"
                    :key="field.field"
                    :style="{
                      textAlign: field.align || 'left',
                      position: frozenColumns.includes(field.field) ? 'sticky' : 'relative',
                      left: frozenColumns.includes(field.field) ? '0' : 'auto',
                      zIndex: frozenColumns.includes(field.field) ? 10 : 1,
                      backgroundColor: 'rgb(var(--v-theme-surface))',
                    }"
                  >
                    {{ formatCellValue(row[field.field], field) }}
                  </td>
                </tr>
              </tbody>
            </VTable>

            <!-- Paginación -->
            <div class="d-flex align-center justify-space-between pa-4">
              <div class="d-flex align-center gap-2">
                <span class="text-body-2 text-medium-emphasis">
                  Mostrando {{ (store.page - 1) * store.itemsPerPage + 1 }} - {{ Math.min(store.page * store.itemsPerPage, store.total) }} de {{ store.total }} registros
                </span>
              </div>
              <div class="d-flex align-center gap-2">
                <VSelect
                  v-model="store.itemsPerPage"
                  :items="[25, 50, 100, 200]"
                  density="compact"
                  variant="outlined"
                  hide-details
                  style="min-inline-size: 80px;"
                  @update:model-value="handleItemsPerPageChange"
                />
                <VPagination
                  v-model="store.page"
                  :length="store.totalPages"
                  :total-visible="7"
                  density="compact"
                  @update:model-value="handlePageChange"
                />
              </div>
            </div>
          </div>

          <!-- Estado vacío -->
          <div
            v-else-if="!loading && !reportConfig"
            class="d-flex align-center justify-center"
            style="block-size: 400px;"
          >
            <VAlert
              type="info"
              variant="tonal"
              text="No se encontró configuración del reporte"
            />
          </div>
        </VCardText>
      </VCard>
    </div>

    <!-- Diálogos -->
    <!-- Export Dialog -->
    <VDialog
      v-model="showExportDialog"
      max-width="400"
    >
      <VCard>
        <VCardTitle>Exportar reporte</VCardTitle>
        <VCardText>
          <VList>
            <VListItem
              v-for="format in availableExportFormats"
              :key="format.id"
              @click="exportReport(format.id)"
            >
              <template #prepend>
                <VIcon
                  :icon="format.icon"
                  :color="format.color"
                />
              </template>
              <VListItemTitle>{{ format.name }}</VListItemTitle>
            </VListItem>
          </VList>
        </VCardText>
      </VCard>
    </VDialog>

    <!-- Share Dialog -->
    <VDialog
      v-model="showShareDialog"
      max-width="500"
    >
      <VCard>
        <VCardTitle>Compartir reporte</VCardTitle>
        <VCardText>
          <VTextField
            v-model="shareLink"
            label="Link de compartir"
            readonly
            variant="outlined"
          />
        </VCardText>
        <VCardActions>
          <VBtn @click="copyShareLink">
            Copiar link
          </VBtn>
          <VSpacer />
          <VBtn
            variant="text"
            @click="showShareDialog = false"
          >
            Cerrar
          </VBtn>
        </VCardActions>
      </VCard>
    </VDialog>
  </div>
</template>

